/** Native dialog and dataset-list acceptance with isolated, production-generated package pages. */
async page => {
  const assert = (value, message) => { if (!value) throw new Error(message) }
  const errors = [], error = value => errors.push(value.message)
  page.on('pageerror', error)
  const media = route => route.fulfill({ status: 200, contentType: 'image/svg+xml', body: '<svg xmlns="http://www.w3.org/2000/svg" width="400" height="200"><rect width="400" height="200" fill="#496252"/></svg>' })
  await page.route('**/api/visual-curator/resource**', media)
  try {
    await page.setViewportSize({ width: 1440, height: 1000 }); await page.reload()
    await page.getByRole('tab', { name: '数据集', exact: true }).click()
    const rows = page.locator('[data-dataset-row]')
    await rows.first().waitFor()
    assert(await rows.count() === 3, 'Frozen complete packages and negative observations must remain available')
    const mixed = rows.filter({ has: page.locator('.vc-dataset-coverage[data-scope="all"]') }).first()
    assert((await mixed.locator('.vc-dataset-role-counts').textContent()).includes('正例参考 4') && (await mixed.locator('.vc-dataset-role-counts').textContent()).includes('反例参考 4'), 'The mixed row must show both frozen role counts')
    const negatives = rows.filter({ has: page.locator('.vc-dataset-coverage[data-scope="negative"]') })
    assert(await negatives.locator('.vc-dataset-package-kind').innerText() === '反例观察包', 'A negative observation package must have an explicit role label')
    assert((await negatives.locator('.vc-dataset-image-count').innerText()).includes('4'), 'Package image counts must be separated from their type label')
    assert(await negatives.locator('.vc-dataset-coverage').evaluate(element => element.getBoundingClientRect().height < 50), 'Observation summaries must remain within two compact lines')
    assert(await mixed.locator('.vc-dataset-coverage').evaluate(element => element.getBoundingClientRect().height < 70), 'Complete-package summaries must keep their rule statistics within a compact third line')
    await page.locator('.vc-datasets-workspace').screenshot({ path: '.playwright-mcp/search-datasets-coverage-desktop.png', animations: 'disabled' })
    assert(await page.locator('.vc-dataset-version-notice').isVisible(), 'A newer profile must be distinguished from existing frozen packages')
    for (const dark of [true, false]) {
      await page.setViewportSize({ width: 390, height: 844 })
      await page.evaluate(dark => document.body.toggleAttribute('data-ds-dark-theme', dark), dark)
      assert(await page.locator('.vc-datasets-panel').evaluate(element => element.scrollWidth <= element.clientWidth + 1), 'Package types and counts must fit the narrow dataset list')
    }
    await page.setViewportSize({ width: 1440, height: 1000 })
    await page.evaluate(() => document.body.setAttribute('data-ds-dark-theme', ''))
    await mixed.getByRole('button', { name: '详情', exact: true }).click()
    const detail = page.getByRole('dialog', { name: '数据集详情', exact: true })
    await detail.getByRole('tab', { name: '逐图观察', exact: true }).click()
    await detail.getByRole('button', { name: '反例参考 · 4', exact: true }).click()
    await page.waitForFunction(() => document.querySelectorAll('.vc-dataset-sample').length >= 3)
    await detail.locator('.vc-dataset-detail-scroll').evaluate(element => { element.scrollTop = element.scrollHeight })
    await page.waitForFunction(() => document.querySelectorAll('.vc-dataset-sample').length === 4)
    assert((await detail.locator('.vc-dataset-sample').allTextContents()).every(text => text.includes('反例参考') && !text.includes('正例参考')), 'Filtered pages must contain negative observations only')
    const negativeReads = await page.evaluate(() => window.datasetQa.sampleReads().filter(read => read.role === 'negative'))
    assert(negativeReads.length === 2 && negativeReads[0].cursor === 'first' && negativeReads[1].cursor !== 'first', 'Negative pages must advance the actual filter-bound cursor once')
    await detail.locator('.vc-dataset-detail-footer').getByRole('button', { name: '关闭', exact: true }).click()
    await rows.last().getByRole('button', { name: '详情', exact: true }).click()
    await detail.getByRole('tab', { name: '逐图观察', exact: true }).click()
    await detail.getByRole('button', { name: '反例参考 · 0', exact: true }).click()
    await detail.getByText('这个数据包中暂无所选角色的观察。', { exact: true }).waitFor()
    await detail.locator('.vc-dataset-detail-footer').getByRole('button', { name: '关闭', exact: true }).click()
    await page.evaluate(() => window.datasetQa.deferEvidence())
    await page.locator('.vc-datasets-heading').getByRole('button', { name: '生成数据集', exact: true }).click()
    const dialog = page.getByRole('dialog', { name: '风格档案', exact: true })
    await dialog.getByText('正在核对最新档案…', { exact: true }).waitFor()
    const generate = dialog.getByRole('button', { name: '生成数据集', exact: true })
    assert(await generate.isDisabled(), 'Generation must remain blocked while the latest profile is unconfirmed')
    assert(await dialog.locator('.vc-profile-evidence-item').count() === 0, 'Deferred observations must not reuse another collection’s evidence')
    await page.evaluate(() => window.datasetQa.releaseRead())
    await page.waitForFunction(() => !Array.from(document.querySelectorAll('.vc-profile-dialog button')).find(button => button.textContent === '生成数据集')?.disabled)
    const choices = dialog.getByRole('group', { name: '导出范围', exact: true })
    assert(await choices.getByRole('button').count() === 3, 'All three export scopes must be available')
    await page.evaluate(() => window.datasetQa.deferEvidence(true))
    await dialog.getByText('正在核对最新档案…', { exact: true }).waitFor()
    assert(await generate.isDisabled(), 'A replaced analysis must load its evidence before allowing generation')
    await page.evaluate(() => window.datasetQa.releaseRead())
    await page.waitForFunction(() => !Array.from(document.querySelectorAll('.vc-profile-dialog button')).find(button => button.textContent === '生成数据集')?.disabled)
    await page.evaluate(() => window.datasetQa.markRoleObservations())
    const evidencePane = dialog.locator('.vc-profile-evidence'), imageNames = () => evidencePane.locator('.vc-profile-evidence-item img').evaluateAll(images => images.map(image => image.alt))
    const completeEvidence = await imageNames()
    await choices.getByRole('button', { name: '仅反例观察 · 4', exact: true }).click()
    await evidencePane.evaluate(element => { element.scrollTop = element.scrollHeight })
    const negativeNames = await page.evaluate(() => window.datasetQa.previewSamples('negative'))
    await page.waitForFunction(expected => JSON.stringify(Array.from(document.querySelectorAll('.vc-profile-evidence-item img')).map(image => image.alt)) === JSON.stringify(expected), negativeNames)
    assert((await evidencePane.innerText()).includes('negative reference observation'), 'Role previews must show observations beyond the selected rule dimension')
    assert((await evidencePane.innerText()).includes('当前显示'), 'The preview count must use localized copy')
    await choices.getByRole('button', { name: '仅正例观察 · 4', exact: true }).click()
    await evidencePane.evaluate(element => { element.scrollTop = element.scrollHeight })
    const positiveNames = await page.evaluate(() => window.datasetQa.previewSamples('positive'))
    await page.waitForFunction(expected => JSON.stringify(Array.from(document.querySelectorAll('.vc-profile-evidence-item img')).map(image => image.alt)) === JSON.stringify(expected), positiveNames)
    await choices.getByRole('button', { name: '完整参考包 · 8', exact: true }).click()
    assert(JSON.stringify(await imageNames()) === JSON.stringify(completeEvidence), 'Complete-package mode must restore the selected rule evidence')
    await choices.getByRole('button', { name: '仅反例观察 · 4', exact: true }).click()
    const previousReads = await page.evaluate(() => window.datasetQa.sampleReads().length)
    await page.evaluate(() => window.datasetQa.previewCount(30))
    assert(await evidencePane.locator('.vc-profile-evidence-item').count() < 30, 'Large role previews must render incrementally')
    const beforeScroll = await evidencePane.locator('.vc-profile-evidence-item').count()
    await evidencePane.evaluate(element => { element.scrollTop = element.scrollHeight })
    await page.waitForFunction(previous => document.querySelectorAll('.vc-profile-evidence-item').length > previous, beforeScroll)
    assert(await page.evaluate(() => window.datasetQa.sampleReads().length) === previousReads, 'Changing role preview pages must reuse saved profile samples')
    await page.evaluate(() => window.datasetQa.previewCount(0))
    assert((await dialog.locator('.vc-profile-export-options').innerText()).includes('不含风格匹配规则'), 'Observation packages must explain their data-only meaning')
    for (const dark of [true, false]) {
      await page.setViewportSize({ width: 390, height: 844 })
      await page.evaluate(dark => document.body.toggleAttribute('data-ds-dark-theme', dark), dark)
      assert(await dialog.evaluate(element => { const r = element.getBoundingClientRect(); return r.left >= 0 && r.right <= innerWidth && r.top >= 0 && r.bottom <= innerHeight && element.scrollWidth <= element.clientWidth + 1 }), 'Export controls must fit a narrow viewport')
    }
    await page.setViewportSize({ width: 1440, height: 1000 })
    await page.evaluate(() => { document.body.setAttribute('data-ds-dark-theme', ''); window.datasetQa.negativeOnly() })
    assert(await generate.isEnabled(), 'A negative-only profile must be able to generate observations without active rules')
    await dialog.screenshot({ path: '.playwright-mcp/dataset-negative-observations.png', animations: 'disabled' })
    await generate.click()
    await page.waitForFunction(() => window.datasetQa.exportedScopes().length === 1)
    assert(await page.evaluate(() => window.datasetQa.exportedScopes()[0]) === 'negative', 'The accepted submission must retain the selected role')
    await dialog.locator('.vc-profile-footer').getByRole('button', { name: '关闭', exact: true }).click()
    await dialog.waitFor({ state: 'hidden' })
    assert(await page.evaluate(() => window.datasetQa.starts()) === 1, 'Closing before acknowledgement must not repeat generation')
    await page.evaluate(() => window.datasetQa.acknowledge())
    assert(errors.length === 0, 'Role export interactions must not produce browser errors')
    const result = { exportChoices: ['all', 'positive', 'negative'], roleCountsVisible: true, distinctPackageTypes: true, separatedImageCounts: true, compactCoverage: true, newProfileNotice: true, reconciliationExplained: true, deferredEvidenceRestored: true, changedAnalysisRefreshesOpenDialog: true, roleFilterBeforePaging: true, scopeImagesAndObservations: true, completeEvidenceRestored: true, incrementalCachedRolePreview: true, emptyRoleExplained: true, negativePages: negativeReads.length, negativeOnlyGeneration: true, frozenSubmissionScope: 'negative', closeWhileSubmitting: true, narrowOverflow: false, themes: ['dark', 'light'], pageErrors: errors }
    const expected = await page.evaluate(async () => (await fetch('/dataset-roles-ui.expected.json')).json())
    assert(JSON.stringify(result) === JSON.stringify(expected), 'Role export results must match their saved user-flow expectation')
    return result
  } finally { page.off('pageerror', error); await page.unroute('**/api/visual-curator/resource**', media) }
}
